using System.Security.Cryptography;using System.Text;using System.Text.Json;
namespace QuantForge.Core;
public sealed record ResearchWorkspaceAlertBundle(string Fingerprint,string WorkspaceFingerprint,IReadOnlyList<ResearchWorkspaceAlert> Alerts);
public static class ResearchWorkspaceAlertBundleRules
{public static ResearchWorkspaceAlertBundle Create(ResearchWorkspaceIndex index){ResearchWorkspaceIndexRules.Validate(index);var alerts=ResearchWorkspaceAlertRules.Create(index).ToArray();var text=index.IndexFingerprint+"|"+string.Join("|",alerts.Select(x=>$"{x.Severity}:{x.Code}:{x.Message}"));var fp=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text)));return new(fp,index.IndexFingerprint,alerts);}public static void Validate(ResearchWorkspaceAlertBundle value){if(string.IsNullOrWhiteSpace(value.Fingerprint)||string.IsNullOrWhiteSpace(value.WorkspaceFingerprint))throw new InvalidOperationException("Workspace alert bundle identity is incomplete.");}}
public sealed class ResearchWorkspaceAlertBundleFileStore{private readonly string _path;public ResearchWorkspaceAlertBundleFileStore(string path)=>_path=Path.GetFullPath(path);public void Save(ResearchWorkspaceAlertBundle value){ResearchWorkspaceAlertBundleRules.Validate(value);Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public ResearchWorkspaceAlertBundle Load(){var v=JsonSerializer.Deserialize<ResearchWorkspaceAlertBundle>(File.ReadAllText(_path))??throw new InvalidOperationException("Workspace alert bundle is invalid.");ResearchWorkspaceAlertBundleRules.Validate(v);return v;}}
